using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows.Forms;
using KeePassLib;
using KeePassLib.Keys;
using KeePassLib.Serialization;
namespace WinUp {
    static class NotesCodesProbe {
        static int count;
        static void Check(string name,bool ok){if(!ok)throw new Exception(name);Console.WriteLine("PASS "+name);count++;}
        [STAThread]static int Main(){try{if(!Path.GetFileName(Paths.Root).StartsWith("notes-qa-")||KdbxStore.Exists)throw new Exception("Fresh synthetic lab only");AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>new AssemblyName(e.Name).Name=="KeePassLib"?CoreLoader.Resolve():EmbeddedModules.Resolve(e.Name);Run();Console.WriteLine("RESULT passed="+count+" failed=0");return 0;}catch(Exception ex){Console.WriteLine("FAIL "+ex);return 1;}}
        static void Run(){
            Application.EnableVisualStyles();const string pw="Notes-Only-Synthetic!2026";const string secret="SYNTHETIC-NOTE-Жук-42";var store=KdbxStore.Create(pw,null);string recovery=store.MakeRecoveryCode();string id=store.PutNote(null,"Учебная заметка",secret);store.Save();Check("Note separated from accounts",store.NoteItems().Count==1&&store.Entries.Count==0);Check("Note roundtrip in memory",store.ReadNote(id)==secret);
            var db=new PwDatabase();var key=new CompositeKey();key.AddUserKey(new KcpPassword(pw));db.Open(IOConnectionInfo.FromPath(Paths.KdbxFile),key,null);var entry=db.RootGroup.GetEntries(true).Single(e=>e.Strings.ReadSafe("WinUp.Kind")=="note");Check("Independent KeePass sees protected note",entry.Strings.Get("Notes").IsProtected&&entry.Strings.ReadSafe("Notes")==secret);db.Close();Check("Note body absent from encrypted disk",!System.Text.Encoding.UTF8.GetString(File.ReadAllBytes(Paths.KdbxFile)).Contains(secret));
            store.Lock();int left;StoreResult result;store=KdbxStore.Open(pw,null,out left,out result);Check("Reopen note",result==StoreResult.Ok&&store.ReadNote(id)==secret);store.PutNote(id,"Изменённая заметка",secret+"-edited");store.Save();store.DeleteNote(id);store.Save();Check("Deleted note in trash",store.NoteItems().Count==0&&store.DeletedRecords().Any(r=>r.Id==id&&r.Kind=="note"));store.RestoreDeleted(id);store.Save();Check("Restored note stays separate",store.NoteItems().Count==1&&store.Entries.Count==0&&store.ReadNote(id)==secret+"-edited");Check("Notes group excluded from account groups",!store.AccountGroups().Any(g=>g.Name=="Заметки"));store.Lock();store=KdbxStore.OpenByRecovery(recovery,out left,out result);Check("Recovery includes notes",result==StoreResult.Ok&&store.ReadNote(id)==secret+"-edited");
            foreach(var format in new[]{"QR_CODE","CODE_128","EAN_13"}){string data=format=="QR_CODE"?"https://example.test/Заметка?x=42":format=="EAN_13"?"5901234123457":"WINUP-12345";using(var bitmap=CodeImages.Create(data,format)){var lib=Assembly.Load(File.ReadAllBytes(Path.Combine(Paths.Root,"zxing.dll")));var reader=Activator.CreateInstance(lib.GetType("ZXing.BarcodeReader"));var decoded=reader.GetType().GetMethod("Decode",new[]{typeof(Bitmap)}).Invoke(reader,new object[]{bitmap});Check("Generate and decode "+format,decoded!=null&&(string)decoded.GetType().GetProperty("Text").GetValue(decoded,null)==data);}}
            bool rejected=false;try{CodeImages.Create("bad-number","EAN_13");}catch(IOException){rejected=true;}Check("Invalid barcode rejected",rejected);
            var active=store;using(var window=new NotesWindow(store,()=>active,v=>{v.Save();return true;},()=>{},()=>false)){window.SelectNote(id);var editor=(TextBox)typeof(NotesWindow).GetField("text",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(window);Check("Detached note loads before showing window",editor.Text==secret+"-edited");window.Show();Application.DoEvents();editor.Text="SYNTHETIC-DETACHED-EDIT";for(int i=0;i<20;i++){Application.DoEvents();System.Threading.Thread.Sleep(100);}Check("Detached editor autosaves to same KDBX",store.ReadNote(id)==editor.Text);using(var bitmap=new Bitmap(window.Width,window.Height)){window.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(Path.Combine(Paths.Root,"notes-window.png"));}window.NewNote();Check("New note starts empty",editor.Text=="");}
            using(var dialog=new CodeImageDialog()){dialog.Show();Application.DoEvents();var content=(TextBox)typeof(CodeImageDialog).GetField("content",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(dialog);var image=(PictureBox)typeof(CodeImageDialog).GetField("preview",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(dialog);content.Text="https://example.test/winup";typeof(CodeImageDialog).GetMethod("Generate",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(dialog,null);Check("Code dialog generates preview",image.Image!=null);using(var bitmap=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(Path.Combine(Paths.Root,"code-window.png"));}image.Image.Save(Path.Combine(Paths.Root,"qr-export.png"),System.Drawing.Imaging.ImageFormat.Png);Check("PNG export can reopen",new FileInfo(Path.Combine(Paths.Root,"qr-export.png")).Length>100);content.Text="changed";Check("Changed input clears old preview",image.Image==null);}
            var login=new LoginEntry{Name="Учебный аккаунт",RecoveryCodes="CODE-A\nCODE-B"};using(var view=new RecoveryCodesView(login)){Check("Recovery viewer has separate list",view.Controls.Count>0&&view.Value=="CODE-A\nCODE-B");}login.ClearSecrets();store.Lock();
        }
    }
}
